  0% { transform: translateZ(0px); }
  100% { transform: translate3d(-97.5%, 0px, 0px); }
}
@keyframes jump { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(-3px); }
  100% { transform: translateY(0px); }
}
@keyframes avatarFadeLarge { 
  0% { opacity: 0; transform: scale(0.4) translateY(-2px) translate(3px); }
  30% { opacity: 1; }
  100% { opacity: 1; transform: scale(1) translate(-36px, 10px); }
}
@keyframes avatarFadeSmall { 
  0% { transform: scale(1) translate(-36px, 10px); }
  60% { opacity: 1; }
  100% { opacity: 0; transform: scale(0.4) translateY(-2px) translate(3px); }
}
@keyframes fadeOut { 
  0% { opacity: 1; }
  100% { opacity: 0; }
}
@keyframes fadeIn { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}
@keyframes headerSlideDown { 
  0% { opacity: 0; }
  100% { opacity: 1; }
}
@keyframes living-status { 
  0% { height: 4px; }
  100% { height: 9px; }
}
@keyframes skeleton-loading { 
  0% { background-position: 100% 50%; }
  100% { background-position: 0px 50%; }
}

